// Claude branding (31 Okt 2026): semua teks tampilan "Paperclip" jadi "Digital Strategi", termasuk pesan agent.
// Kotak ketik & blok kode dilewati supaya isi ketikan dan perintah teknis tetap utuh. Observer jalan sebelum paint.
const MEREK = "Digital Strategi";
const RE = /\bPaperclip\b/g;
const LEWATI = "script,style,code,pre,textarea,input,[contenteditable],.ProseMirror,.cm-editor,.monaco-editor";
const ATRIBUT = ["placeholder", "title", "aria-label", "alt"];

const ganti = (s: string) => s.replace(RE, MEREK);

function prosesTeks(node: Node) {
  const v = node.nodeValue;
  if (!v || !v.includes("Paperclip") || node.parentElement?.closest(LEWATI)) return;
  node.nodeValue = ganti(v);
}
function prosesElemen(el: Element) {
  if (el.closest(LEWATI)) return;
  for (const a of ATRIBUT) {
    const v = el.getAttribute(a);
    if (v && v.includes("Paperclip")) el.setAttribute(a, ganti(v));
  }
}
function proses(root: Node) {
  if (root.nodeType === Node.TEXT_NODE) return prosesTeks(root);
  if (root.nodeType !== Node.ELEMENT_NODE) return;
  prosesElemen(root as Element);
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  let n = w.nextNode();
  while (n) {
    if (n.nodeType === Node.TEXT_NODE) prosesTeks(n);
    else prosesElemen(n as Element);
    n = w.nextNode();
  }
}

export function startBranding() {
  const win = window as unknown as { __brandDS?: boolean };
  if (typeof window === "undefined" || win.__brandDS) return;
  win.__brandDS = true;
  const judul = () => {
    if (document.title.includes("Paperclip")) document.title = ganti(document.title);
  };
  const obs = new MutationObserver((muts) => {
    for (const m of muts) {
      if (m.type === "childList") m.addedNodes.forEach(proses);
      else proses(m.target);
    }
    judul();
  });
  proses(document.documentElement);
  judul();
  obs.observe(document.documentElement, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATRIBUT });
}
