export function WallCabinetModel({
  item,
  onPointerDown,
  onPointerOver,
  onPointerOut,
  editMode,
}: BasicFurnitureModelProps) {
  const [wx, , wz] = toWorld(item.x, item.y);
  const width = (item.w ?? 80) * SCALE;
  const elevation = item.elevation ?? 0;
  const yPos = elevation > 0 ? elevation : 0.9;
  const metal = useMemo(() => getBrushedMetalTextures(), []);

  return (
    <group
      position={[wx, yPos, wz]}
      onPointerDown={(event) => {
        if (!editMode) return;
        event.stopPropagation();
        onPointerDown?.(item._uid);
      }}
      onPointerOver={(event) => {
        if (!editMode) return;
        event.stopPropagation();
        onPointerOver?.(item._uid);
      }}
      onPointerOut={(event) => {
        if (!editMode) return;
        event.stopPropagation();
        onPointerOut?.();
      }}
    >
      <mesh castShadow receiveShadow>
        <boxGeometry args={[width, 0.4, 0.25]} />
        <meshStandardMaterial
          color="#434a51"
          roughnessMap={metal.roughnessMap}
          roughness={0.9}
          metalness={0.3}
        />
      </mesh>
      <mesh position={[0, 0, 0.13]}>
        <boxGeometry args={[width - 0.02, 0.38, 0.01]} />
        <meshStandardMaterial
          color="#525960"
          roughnessMap={metal.roughnessMap}
          roughness={0.85}
          metalness={0.3}
        />
      </mesh>
      {width > 0.4 ? (
        <mesh position={[0, 0, 0.135]}>
          <boxGeometry args={[0.005, 0.38, 0.002]} />
          <meshStandardMaterial color="#2f2f2f" />
        </mesh>
      ) : null}
      <mesh position={[0.02, -0.1, 0.14]}>
        <boxGeometry args={[0.01, 0.06, 0.01]} />
        <meshStandardMaterial color="#e6eaef" metalness={0.95} roughness={0.08} />
      </mesh>
      {width > 0.4 ? (
        <mesh position={[-0.02, -0.1, 0.14]}>
          <boxGeometry args={[0.01, 0.06, 0.01]} />
          <meshStandardMaterial color="#e6eaef" metalness={0.95} roughness={0.08} />
        </mesh>
      ) : null}
    </group>
  );
}

